/* TV broadcaster logos for slate-card WATCH rows (all sports).
   Logos are base64 PNG data URIs (height 64, trimmed) because the repo
   push path is text-only. Monochrome marks that would vanish on dark
   glass (ABC, CBS, truTV, Apple TV) are pre-inverted to light versions;
   Peacock/FOX wordmarks are pre-whitened keeping their colour marks;
   Disney+ is pre-lifted. ESPN+, NBA TV and NFL Network have no logo
   here on purpose — they render as ghost text via tvWatchRow.
   Helper: window.tvWatchRow(names) -> WATCH-row HTML or ''. */
window.TV_LOGOS = {
  ESPN: 'data:image/png;base64,',
  ESPN2: 'data:image/png;base64,',
  ABC: 'data:image/png;base64,',
  TNT: 'data:image/png;base64,',
  TRUTV: 'data:image/png;base64,',
  NBC: 'data:image/png;base64,',
  USA: 'data:image/png;base64,',
  PEACOCK: 'data:image/png;base64,',
  FOX: 'data:image/png;base64,',
  FS1: 'data:image/png;base64,',
  CBS: 'data:image/png;base64,',
  PARAMOUNT: 'data:image/png;base64,',
  PRIME: 'data:image/png;base64,',
  APPLETV: 'data:image/png;base64,',
  NHLN: 'data:image/png;base64,',
  HULU: 'data:image/png;base64,',
  DISNEYPLUS: 'data:image/png;base64,'
};
/* Display names per canonical key (used for img alt + text fallback). */
window.TV_NAMES = {
  ESPN: 'ESPN', ESPN2: 'ESPN2', ESPNPLUS: 'ESPN+', ABC: 'ABC', TNT: 'TNT',
  TRUTV: 'truTV', NBC: 'NBC', USA: 'USA Network', PEACOCK: 'Peacock',
  FOX: 'FOX', FS1: 'FS1', CBS: 'CBS', PARAMOUNT: 'Paramount+',
  PRIME: 'Prime Video', APPLETV: 'Apple TV', NHLN: 'NHL Network',
  NBATV: 'NBA TV', NFLN: 'NFL Network', HULU: 'Hulu', DISNEYPLUS: 'Disney+'
};
/* Feed-name variants -> canonical key. Feeds emit all sorts of spellings
   ("USA Net", "Amazon Prime Video", "NHLN", "Fox Sports 1", ...). */
var TV_ALIASES = {
  'ESPN': 'ESPN', 'ESPN2': 'ESPN2', 'ESPN 2': 'ESPN2',
  'ESPN+': 'ESPNPLUS', 'ESPN PLUS': 'ESPNPLUS', 'ESPNPLUS': 'ESPNPLUS',
  'ABC': 'ABC', 'TNT': 'TNT', 'TRUTV': 'TRUTV', 'TRU TV': 'TRUTV',
  'NBC': 'NBC', 'USA': 'USA', 'USA NETWORK': 'USA', 'USA NET': 'USA',
  'PEACOCK': 'PEACOCK', 'FOX': 'FOX', 'FS1': 'FS1',
  'FOX SPORTS 1': 'FS1', 'FOX SPORTS ONE': 'FS1',
  'CBS': 'CBS', 'PARAMOUNT+': 'PARAMOUNT', 'PARAMOUNT PLUS': 'PARAMOUNT',
  'PRIME VIDEO': 'PRIME', 'AMAZON PRIME VIDEO': 'PRIME', 'AMAZON PRIME': 'PRIME',
  'APPLE TV': 'APPLETV', 'APPLE TV+': 'APPLETV', 'APPLE TV PLUS': 'APPLETV',
  'MLS SEASON PASS': 'APPLETV',
  'NHL NETWORK': 'NHLN', 'NHLN': 'NHLN',
  'NBA TV': 'NBATV', 'NBATV': 'NBATV',
  'NFL NETWORK': 'NFLN', 'NFLN': 'NFLN',
  'HULU': 'HULU', 'DISNEY+': 'DISNEYPLUS', 'DISNEY PLUS': 'DISNEYPLUS'
};
window.tvKey = function (name) {
  if (!name) return null;
  var k = String(name).trim().replace(/\s+/g, ' ').toUpperCase();
  return TV_ALIASES[k] || null;
};
function tvEsc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
/* WATCH row for a slate card: ghosted broadcaster logos (opacity handled
   by .watch-row CSS), right-aligned, max 3, deduped. Names that map to a
   canonical key without a logo (ESPN+, NBA TV, NFL Network) and unmapped
   names (local RSNs etc.) render as ghost text. Returns '' when there is
   nothing to show — cards only get a row when a feed actually named a
   broadcaster; nothing is ever guessed. */
window.tvWatchRow = function (names) {
  if (!names || !names.length) return '';
  var seen = {}, items = [];
  for (var i = 0; i < names.length; i++) {
    if (names[i] == null) continue;
    var raw = String(names[i]).trim().replace(/\s+/g, ' ');
    if (!raw) continue;
    var key = window.tvKey(raw);
    var id = key || ('T:' + raw.toUpperCase());
    if (seen[id]) continue;
    seen[id] = 1;
    items.push({ key: key, label: key ? (window.TV_NAMES[key] || raw) : raw });
  }
  if (!items.length) return '';
  var hasLogo = function (it) { return !!(it.key && window.TV_LOGOS[it.key]); };
  var pick = items.filter(hasLogo).concat(items.filter(function (it) { return !hasLogo(it); })).slice(0, 3);
  var inner = pick.map(function (it) {
    if (hasLogo(it)) return '<img class="watch-logo" src="' + window.TV_LOGOS[it.key] + '" alt="' + tvEsc(it.label) + '">';
    return '<span class="watch-txt">' + tvEsc(it.label) + '</span>';
  }).join('');
  return '<div class="watch-row"><span class="watch-lbl">WATCH</span><span class="watch-logos">' + inner + '</span></div>';
};
